import{describe,it,expect}from"vitest";import{statesData,checkAdjacency,verifyQuizAnswer,getAchievements,calculateJourneyPath,filterStatesList}from"../../frontend/state-challenge/state-challenge.js";const REQUIRED_STATE_FIELDS=["id","name","capital","neighbors","quiz","coords"];describe("State Challenge Dataset Integrity",()=>{it("contains exactly 29 states in the dataset",()=>{expect(statesData.length).toBe(29)}),it("every state contains all required fields with non-empty values",()=>{statesData.forEach((e,t)=>{REQUIRED_STATE_FIELDS.forEach(s=>{expect(e,`State at index ${t} missing field ${s}`).toHaveProperty(s),"neighbors"===s?(expect(Array.isArray(e.neighbors)).toBe(!0),expect(e.neighbors.length).toBeGreaterThan(0)):"quiz"===s?(expect(e.quiz).toHaveProperty("question"),expect(e.quiz).toHaveProperty("answer"),expect(typeof e.quiz.question).toBe("string"),expect(typeof e.quiz.answer).toBe("string"),expect(e.quiz.question.trim().length).toBeGreaterThan(0),expect(e.quiz.answer.trim().length).toBeGreaterThan(0)):"coords"===s?(expect(typeof e.coords.x).toBe("number"),expect(typeof e.coords.y).toBe("number")):(expect(typeof e[s]).toBe("string"),expect(e[s].trim().length).toBeGreaterThan(0))})})}),it("all state IDs and coordinates are unique",()=>{const e=statesData.map(e=>e.id),t=new Set(e);expect(t.size).toBe(e.length);const s=new Set(statesData.map(e=>`${e.coords.x},${e.coords.y}`));expect(s.size).toBe(statesData.length)}),it("verifies symmetry of neighbors (for every connection A -> B, there is B -> A)",()=>{statesData.forEach(e=>{e.neighbors.forEach(t=>{const s=statesData.find(e=>e.id===t);expect(s,`Neighbor ${t} listed by ${e.id} does not exist in dataset`).toBeDefined(),expect(s.neighbors,`Symmetry failure: ${e.id} has ${t} as neighbor, but ${t} does not list ${e.id}`).toContain(e.id)})})})}),describe("State Challenge Game Logic",()=>{it("correctly checks adjacency between neighbors",()=>{expect(checkAdjacency("JK","HP")).toBe(!0),expect(checkAdjacency("JK","TN")).toBe(!1)}),it("verifies quiz answers case-insensitively",()=>{expect(verifyQuizAnswer("JK","dal lake")).toBe(!0),expect(verifyQuizAnswer("JK","  Dal Lake  ")).toBe(!0),expect(verifyQuizAnswer("JK","Wular Lake")).toBe(!1)}),it("handles invalid inputs gracefully in checkAdjacency and verifyQuizAnswer",()=>{expect(checkAdjacency(null,"HP")).toBe(!1),expect(checkAdjacency("JK",void 0)).toBe(!1),expect(verifyQuizAnswer(null,"answ")).toBe(!1),expect(verifyQuizAnswer("JK","")).toBe(!1)}),it("calculates the shortest journey path between states",()=>{const e=calculateJourneyPath("JK","PB");expect(e.length).toBeGreaterThan(0),expect(e[0]).toBe("JK"),expect(e[e.length-1]).toBe("PB")}),it("filters states list by search query",()=>{const e=filterStatesList(statesData,"himachal");expect(e.length).toBe(1),expect(e[0].id).toBe("HP")})}),describe("State Challenge Achievements & Badges",()=>{it("unlocks Border Crosser upon first crossing",()=>{const e=getAchievements(["GJ","RJ"]).map(e=>e.id);expect(e).toContain("bordercrosser")}),it("unlocks Coastal Cruiser when crossing 4 coastal states",()=>{const e=getAchievements(["MH","GA","KA","KL"]).map(e=>e.id);expect(e).toContain("coastal")}),it("unlocks Himalayan Explorer when crossing 3 Himalayan states",()=>{const e=getAchievements(["JK","HP","UK"]).map(e=>e.id);expect(e).toContain("himalayan")}),it("unlocks Seven Sisters badge when crossing 4 Northeastern states",()=>{const e=getAchievements(["AS","AR","NL","MN"]).map(e=>e.id);expect(e).toContain("sevensisters")}),it("unlocks The Great Traverse when path length is 8 or more",()=>{const e=getAchievements(["JK","HP","PB","HR","UP","MP","MH","KA"]).map(e=>e.id);expect(e).toContain("traverse")}),it("returns empty array when journey is empty",()=>{expect(getAchievements([])).toEqual([]),expect(getAchievements(null)).toEqual([])})});